package name.boyle.chris.sgtpuzzles.parity

import name.boyle.chris.sgtpuzzles.engine.Fifteen
import name.boyle.chris.sgtpuzzles.engine.Midend
import org.junit.Assert.assertEquals
import org.junit.Test
import java.io.File

/**
 * Level: semantic. Game: fifteen.
 *
 * `params + seed -> DESC` must match upstream bit for bit. The frozen
 * goldens are generated by C; the test also samples fresh seeds against
 * the oracle so the golden file is not the only coverage.
 */
class FifteenDescTest {

    private val testdata = File(
        System.getProperty("testdata") ?: error("testdata system property is not set"),
    )

    @Test
    fun `the frozen descriptions match the Kotlin generator`() {
        val golden = Json.parse(File(testdata, "golden/fifteen/desc.json").readText()) as JsonValue.Obj
        val seed = golden.string("seed")
        val entries = (golden.field("entries") as JsonValue.Arr).items

        for (item in entries) {
            val entry = item as JsonValue.Obj
            val params = entry.string("params")
            val expected = entry.string("id")
            val actual = Midend.newGame(Fifteen, params, seed).id()
            assertEquals("fifteen '$params' seed=$seed", expected, actual)
        }
    }

    @Test
    fun `fresh seeds match the oracle`() = OracleClient().use { oracle ->
        val paramsList = listOf("4x4", "5x5", "6x6", "3x2", "2x5", "7x3")
        val seeds = listOf("1", "2", "12345", "seed", "another seed", "0", "-7")
        for (params in paramsList) {
            for (seed in seeds) {
                val expected = oracle.newGame("fifteen", params, seed).id
                val actual = Midend.newGame(Fifteen, params, seed).id()
                assertEquals("fifteen '$params' seed=$seed", expected, actual)
            }
        }
    }
}
